import { ChipSelector, IChipSelectorConfig } from './chip-selector';
import { Container } from 'pixi.js';
import { BaseCabinet, ICabinetOptions } from '../base-cabinet';
import { CabinetButtonView, OneHandedPlaySetting, OneHandedPlaySettingStrings } from '@game-studio/cabinet';
import { AssetManager } from '@game-studio/asset-manager';
import { container, environment, eventEmitter } from '../..';
import { casinoCabinetAssets } from './asset-list';
import { inversifyContainer } from '../../inversify/container';
import { BaseChip } from './base-chip';

import gsap from 'gsap';

const PADDING: number = 8;

export interface ICasinoCabinetOptions extends ICabinetOptions{
    showChipSelector?: boolean;
    chipSelectorConfig?: IChipSelectorConfig;
}

export class CasinoCabinet extends BaseCabinet {

    private _casinoOptions?: ICasinoCabinetOptions;

    private _casinoComponents: Container;
    public get casinoComponents(): Container {
        return this._casinoComponents;
    }
    private _chipSelector: ChipSelector;
    public get chipSelector(): ChipSelector {
        return this._chipSelector;
    }

    private _clearButton: CabinetButtonView;
    private _undoButton: CabinetButtonView;
    private _repeatLastBetButton: CabinetButtonView;

    constructor(gameOptions?: ICasinoCabinetOptions) {
        super(gameOptions);
        this._casinoOptions = gameOptions;
    }

    protected setToBuyState(): void {
        if (this.inFreePlay) {
            this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.freePlay);
            this.animateStakeText('');
            this.disablePurchaseButton();
        } else {
            this.updatePurchaseMainText(inversifyContainer.cabinetConfig.buttonTexts.buy);
            this.showPurchaseText();
            this.animateStakeText('-');
        }
        this.holdSpinnerDuration = this._autoBuyPopupDelayS;
    }

    protected onPurchaseError(): void {
        super.onPurchaseError(true);
        this.enablePurchaseButton();
    }

    public async init(): Promise<void> {
        await super.init(); 

        await this.loadCasinoAssets();

        this._cabinetView.infoButton.changeButtonTexture(AssetManager.getTexture('casino-cabinet-chat-bubble'));

        this._casinoComponents = new Container();
        this.addChild(this._casinoComponents);

        this._chipSelector = new ChipSelector(this._casinoOptions?.chipSelectorConfig);
        this._casinoComponents.addChild(this._chipSelector);

        this._clearButton = new CabinetButtonView(
            AssetManager.getTexture('casino-cabinet-clear'),
            [{ pointerEvent: 'pointerup', callback: () => { eventEmitter.emit('CASINO_CABINET_CLEAR'); } }]
        );
        
        this._casinoComponents.addChild(this._clearButton);
        this._clearButton.name = 'cabinet-clear-stake-button';

        this._undoButton = new CabinetButtonView(
            AssetManager.getTexture('casino-cabinet-undo'),
            [{ pointerEvent: 'pointerup', callback: () => { eventEmitter.emit('CASINO_CABINET_UNDO'); } }]
        );
        this._casinoComponents.addChild(this._undoButton);
        this._clearButton.name = 'cabinet-undo-stake-button';

        this._repeatLastBetButton = new CabinetButtonView(
            AssetManager.getTexture('casino-cabinet-repeat'),
            [{ pointerEvent: 'pointerup', callback: () => { eventEmitter.emit('CASINO_CABINET_REPEAT'); } }]
        );
        this._casinoComponents.addChild(this._repeatLastBetButton);
        this._repeatLastBetButton.name = 'cabinet-repeat-stake-button';

        if (!this.inFreePlay) {
            container.cabinet.updatePurchaseText('-');
        }
        container.cabinet.hideStakeButtons();

        eventEmitter.on('GAME_BEGIN', this.onBeginGame.bind(this));
        eventEmitter.on('GAME_COMPLETE', this.onGameComplete.bind(this));
    }

    public setCurrentBalance(amount: string): void {
        if (!this.inFreePlay) {
            super.setCurrentBalance(amount);
        } else {
            super.setCurrentBalance('');
        }
    }

    public enablePurchaseButton(): void {
        if (!this.inFreePlay) {
            super.enablePurchaseButton();
        }
    }

    public updatePurchaseText(amount: string): void {
        if (!this.inFreePlay) {
            super.updatePurchaseText(amount);
        } else {
            super.updatePurchaseText('');
        }
    }

    private onBeginGame(): void {
        this._casinoComponents.interactiveChildren = false;
        this._chipSelector.disableInteractivity();
        gsap.to(this._casinoComponents, { alpha: 0, duration: 0.5, onComplete: () => { this._casinoComponents.renderable = false; } });
    }

    public onResumeGame(): void {
        this._casinoComponents.interactiveChildren = false;
        this._chipSelector.disableInteractivity();
        this._casinoComponents.renderable = false;
    }

    private onGameComplete(): void {
        this._casinoComponents.interactiveChildren = true;
        this._chipSelector.enableInteractivity();
        this._casinoComponents.renderable = true;
        gsap.to(this._casinoComponents, { alpha: 1, duration: 0.5 });
    }

    public setChips(chips: BaseChip[]) {
        this._chipSelector.addChips(chips);
    }

    public async endGame(): Promise<void> {
        await super.endGame();
        container.cabinet.updatePurchaseText('-');
    }

    private async loadCasinoAssets(): Promise<void> {
        casinoCabinetAssets.baseUrl = inversifyContainer.endPoints.urls[environment].cdnRoot;
        await AssetManager.load(casinoCabinetAssets);
    }

    public handleOrientationChange() {
        super.handleOrientationChange();
        
        this.handleCasinoResize(this._userPrefs.oneHandedPlay);
    }

    private handleCasinoResize(oneHandedSetting: OneHandedPlaySetting | OneHandedPlaySettingStrings): void {
        this._casinoComponents.scale.set(this._cabinetView.scale.x, this._cabinetView.scale.y);

        const targetWidth: number = (this.CabinetDimensions.width / this._casinoComponents.scale.x);
        const maxHeight: number = this._clearButton.height * 1.3;
        const targetChipSelectorWidth: number = targetWidth - (this._clearButton.width + this._undoButton.width + this._repeatLastBetButton.width + (PADDING * 3));
        
        this._chipSelector.resize(targetChipSelectorWidth, maxHeight);

        switch (oneHandedSetting) {
            case OneHandedPlaySetting.left:
                this._chipSelector.position.set(-targetWidth * 0.5, 0);
                this._clearButton.x = this._chipSelector.x + targetChipSelectorWidth + PADDING;
                this._undoButton.x = this._clearButton.x + this._clearButton.width + PADDING;
                this._repeatLastBetButton.x = this._undoButton.x + this._undoButton.width + PADDING;
                break;
            case OneHandedPlaySetting.right:
                this._undoButton.x = -targetWidth * 0.5;
                this._repeatLastBetButton.x = this._undoButton.x + this._undoButton.width + PADDING;
                this._clearButton.x = this._repeatLastBetButton.x + this._repeatLastBetButton.width + PADDING;

                this._chipSelector.position.set(targetWidth * 0.5 - this._chipSelector.width, 0);
                break;
            case OneHandedPlaySetting.off:
                this._clearButton.x = -targetWidth * 0.5;
                this._chipSelector.position.set(-this._chipSelector.width * 0.5, 0);
                this._repeatLastBetButton.x = targetWidth * 0.5 - this._repeatLastBetButton.width;
                this._undoButton.x = this._repeatLastBetButton.x - this._undoButton.width - PADDING;

                break;
        }

        this._clearButton.y = this._chipSelector.height - this._clearButton.height;
        this._undoButton.y = this._chipSelector.height - this._undoButton.height;
        this._repeatLastBetButton.y = this._chipSelector.height - this._repeatLastBetButton.height;

        this._casinoComponents.x = this._cabinetView.x;
        this._casinoComponents.y = this._cabinetView.y - this.CabinetDimensions.height - this._casinoComponents.height;
    }

    public changeCabinetLayout(oneHandedSetting: OneHandedPlaySetting | OneHandedPlaySettingStrings): void {
        super.changeCabinetLayout(oneHandedSetting);
        this.handleCasinoResize(oneHandedSetting);
    }

    public playInvalidBetAlert(): void {
        this.chipSelector.playInvalidBetAlert();
    }
}